using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public sealed class InventoryTrackerTests
{
    private InventoryTracker _tracker;

    public InventoryTrackerTests()
    {
        _tracker = new InventoryTracker();
    }

    #region Stock Level Tests

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        var level = _tracker.GetStockLevel("UNKNOWN-SKU");

        Assert.AreEqual(0, level);
    }

    [TestMethod]
    public void AddStock_NewSku_SetsStockLevel()
    {
        _tracker.AddStock("SKU-001", 50);

        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    public void AddStock_ExistingSku_IncrementsStockLevel()
    {
        _tracker.AddStock("SKU-001", 30);
        _tracker.AddStock("SKU-001", 20);

        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-001"));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100)]
    public void AddStock_ZeroOrNegativeQuantity_ThrowsArgumentException(int quantity)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _tracker.AddStock("SKU-001", quantity));
    }

    [TestMethod]
    public void AddStock_NullSku_ThrowsArgumentNullException()
    {
        Assert.ThrowsExactly<ArgumentNullException>(() => _tracker.AddStock(null!, 10));
    }

    [TestMethod]
    public void GetStockLevel_NullSku_ThrowsArgumentNullException()
    {
        Assert.ThrowsExactly<ArgumentNullException>(() => _tracker.GetStockLevel(null!));
    }

    [TestMethod]
    public void AddStock_MultipleSkus_TracksIndependently()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-B", 25);

        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(25, _tracker.GetStockLevel("SKU-B"));
    }

    #endregion

    #region Reorder Alert Tests

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-LOW", 5);

        Assert.IsTrue(_tracker.NeedsReorder("SKU-LOW"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-HIGH", 100);

        Assert.IsFalse(_tracker.NeedsReorder("SKU-HIGH"));
    }

    [TestMethod]
    public void NeedsReorder_UnknownSku_ReturnsTrue()
    {
        // Zero stock should trigger reorder
        Assert.IsTrue(_tracker.NeedsReorder("NEVER-STOCKED"));
    }

    [TestMethod]
    public void NeedsReorder_NullSku_ThrowsArgumentNullException()
    {
        Assert.ThrowsExactly<ArgumentNullException>(() => _tracker.NeedsReorder(null!));
    }

    #endregion
}

